// === Tab: frag ===
const frag = `
	#ifdef GL_ES
	precision mediump float;
	#endif

	varying vec2 vTexCoord;

	uniform vec2 u_resolution;
	uniform float u_time;

	// funzione helper per impulsi morbidi
	float beat(float t, float phase) {
		float x = mod(t + phase, 1.0);
		return exp(-40.0 * x);
	}

	void main() {
		vec2 st = vTexCoord.xy / u_resolution.xy;
		st.x *= u_resolution.x / u_resolution.y;

		float v = sqrt(0.25 - pow(st.y - 0.6, 2.));
		float x1 = 0.62 - v, x2 = 0.62 + v;

		// due impulsi per battito doppio (lub-dub)
		float tBeat = u_time * 2.0;  // 2 battiti al secondo
		float heartbeat = beat(tBeat, 0.0) + 0.5 * beat(tBeat, 0.35);

		float t = clamp((st.x - x1) / (x2 - x1), 0.0, 1.0) + heartbeat;

		if (st.y > 0.5) t += 0.5;

		vec3 a = vec3(0.4, 0.2, 0.7);
		vec3 b = vec3(0.3, 0.3, 0.5);
		vec3 c = vec3(1.0, 1.0, 1.0);
		vec3 d = vec3(0.00, 0.30, 0.20);
		vec3 color = a + b * tan(6.28318530718 * (c * t + d));

		gl_FragColor = vec4(color, 1.0);
	}
`;


// === Tab: vert ===
const vert = `
	attribute vec3 aPosition;
	attribute vec2 aTexCoord;

	varying vec2 vTexCoord;

	void main() {
		vTexCoord = aTexCoord;

		vec4 positionVec4 = vec4(aPosition, 1.0);
		positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

		gl_Position = positionVec4;
	}
`;

